<?php
requireAdmin();require_once __DIR__.'/devolucoes_service.php';$sale=null;$items=[];$error='';$view=null;$returned=[];
if(isset($_GET['venda'])){try{$sale=comprovantePermitido((int)$_GET['venda']);$items=query("SELECT v.* FROM ".vendasLiquidasSql()." v JOIN comprovante_itens ci ON ci.venda_id=v.id WHERE ci.comprovante_id=? ORDER BY v.id",[$sale['id']])->fetchAll();}catch(RuntimeException $e){$error='Venda não encontrada.';}}
if(isset($_GET['ver'])){$view=query('SELECT d.*,u.nome responsavel FROM devolucoes d JOIN usuarios u ON u.id=d.usuario_id WHERE d.id=?',[(int)$_GET['ver']])->fetch();if($view)$returned=query('SELECT i.*,v.produto_nome,v.ferramenta_id FROM devolucao_itens i JOIN vendas v ON v.id=i.venda_id WHERE i.devolucao_id=?',[$view['id']])->fetchAll();}
$tools=query('SELECT id,nome,preco,estoque FROM ferramentas ORDER BY nome')->fetchAll();$history=query('SELECT d.*,u.nome responsavel FROM devolucoes d JOIN usuarios u ON u.id=d.usuario_id ORDER BY d.id DESC LIMIT 100')->fetchAll();page('Devoluções e trocas');?>
<section class="card no-print"><form method="get" class="search"><input type="hidden" name="p" value="devolucoes"><label>Nº da venda / comprovante<input type="number" name="venda" min="1" required value="<?=e($_GET['venda']??'')?>"></label><button>Buscar venda</button></form><p>O gerente registra os itens recebidos e confere a diferença financeira. Itens com avaria podem ser recebidos sem voltar ao estoque disponível. Uma troca exige venda quitada e gera um novo comprovante vinculado.</p></section>
<?php if($error):?><p class="notice"><?=e($error)?></p><?php endif;?>
<?php if($view):?><section class="card"><div class="toolbar"><h2><?=$view['tipo']==='Troca'?'Troca':'Devolução'?> #<?=$view['id']?></h2><button id="print-report" type="button">Imprimir / salvar PDF</button></div><p>Documento demonstrativo, sem valor fiscal. Venda original #<?=$view['comprovante_id']?> · <?=e($view['criado_em'])?> · Responsável: <?=e($view['responsavel'])?></p><p>Motivo: <?=e($view['motivo'])?></p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Item devolvido</th><th>Qtd.</th><th>Voltou ao estoque?</th><th>Total</th></tr></thead><tbody><?php foreach($returned as $r):?><tr><td><?=$r['ferramenta_id']?></td><td><?=e($r['produto_nome'])?></td><td><?=$r['quantidade']?></td><td><?=$r['repor_estoque']?'Sim':'Não — indisponível'?></td><td><?=money($r['total'])?></td></tr><?php endforeach;?></tbody></table></div><p>Devolvido: <?=money($view['total'])?> · Novos itens: <?=money($view['total_novo'])?></p><p><b><?=$view['forma']==='Abatimento boleto'?'Abatimento do valor a receber':((float)$view['diferenca']>0?'Recebido do cliente':((float)$view['diferenca']<0?'Reembolsado ao cliente':'Sem diferença'))?>: <?=money(abs((float)$view['diferenca']))?></b> · <?=e($view['forma'])?> · <?=e($view['referencia'])?></p><?php if($view['novo_comprovante_id']):?><a href="index.php?p=comprovante&id=<?=$view['novo_comprovante_id']?>">Abrir comprovante dos novos itens #<?=$view['novo_comprovante_id']?></a><?php endif;?></section><?php endif;?>
<?php if($sale&&$sale['status']==='Concluída'):?><section class="card no-print"><h2>Venda #<?=$sale['id']?> — <?=e($sale['cliente_nome'])?></h2><p>Pagamento original: <?=e($sale['pagamento_status'])?></p><form method="post" class="form-grid" id="return-form"><?php csrf();?><input type="hidden" name="comprovante_id" value="<?=$sale['id']?>"><input type="hidden" name="chave" value="<?=bin2hex(random_bytes(32))?>"><label>Operação<select name="tipo"><option>Devolução</option><option>Troca</option></select></label><label>Motivo<input name="motivo" maxlength="255" required></label><div class="table-wrap order-items"><table><thead><tr><th>Item original</th><th>Ainda pode devolver</th><th>Devolver</th><th>Repor no estoque</th></tr></thead><tbody><?php foreach($items as $t):?><tr><td>#<?=$t['ferramenta_id']?> · <?=e($t['produto_nome'])?> · <?=money($t['preco_unitario'])?></td><td><?=$t['quantidade_liquida']?></td><td><input type="number" name="devolver[<?=$t['id']?>]" data-return-cents="<?=centavos($t['preco_unitario'])?>" min="0" max="<?=$t['quantidade_liquida']?>" value="0" aria-label="Devolver <?=e($t['produto_nome'])?>"></td><td><input type="checkbox" name="repor[<?=$t['id']?>]" value="1" checked aria-label="Repor <?=e($t['produto_nome'])?>"></td></tr><?php endforeach;?></tbody></table></div>
<div class="table-wrap order-items" data-exchange-items><h2>Novos itens da troca</h2><table><thead><tr><th>ID / ferramenta</th><th>Preço</th><th>Estoque atual</th><th>Quantidade nova</th></tr></thead><tbody><?php foreach($tools as $t):?><tr><td>#<?=$t['id']?> · <?=e($t['nome'])?></td><td><?=money($t['preco'])?></td><td><?=$t['estoque']?></td><td><input type="number" name="quantidades[<?=$t['id']?>]" min="0" max="1000000" value="0" data-new-cents="<?=centavos($t['preco'])?>" aria-label="Nova quantidade de <?=e($t['nome'])?>"></td></tr><?php endforeach;?></tbody></table></div>
<p class="order-items" id="return-total" role="status"></p><label>Meio do recebimento / reembolso<select name="forma"><option value="">Sem diferença / boleto pendente</option><option>Pix</option><option>Cartão de crédito</option></select></label><label>Referência financeira (opcional)<input name="referencia" maxlength="120"></label><label class="check-label"><input type="checkbox" name="financeiro_conferido" value="1"> Conferi o recebimento ou reembolso da diferença</label><p class="order-items">A diferença é novos itens menos itens devolvidos. Positiva: cliente paga; negativa: cliente recebe. Em devolução de boleto pendente, apenas abate o saldo. Registros financeiros são manuais; não há estorno bancário automático.</p><div class="form-footer"><button name="action" value="save_return">Confirmar devolução / troca</button></div></form></section><?php endif;?>
<section class="card no-print"><h2>Últimos 100 registros</h2><div class="table-wrap"><table><thead><tr><th>Nº / tipo</th><th>Venda</th><th>Data</th><th>Devolvido</th><th>Responsável</th><th>Ação</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td>#<?=$h['id']?> · <?=e($h['tipo'])?></td><td>#<?=$h['comprovante_id']?></td><td><?=e($h['criado_em'])?></td><td><?=money($h['total'])?></td><td><?=e($h['responsavel'])?></td><td><a href="index.php?p=devolucoes&ver=<?=$h['id']?>">Abrir</a></td></tr><?php endforeach;if(!$history)emptyRow(6);?></tbody></table></div></section><?php endpage();
